from typing import List


class Solution:
    def findMaximumXOR(self, nums: List[int]) -> int:
        best = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                # XOR all pairs directly.
                best = max(best, nums[i] ^ nums[j])
        return best

